package io.github.diodeme.ji.ai;

import java.util.ArrayList;
import java.util.List;

/** Request-scoped exact-value redactor shared by credentials and custom headers. */
public final class SecretRedactor implements AutoCloseable {
    private final List<char[]> values = new ArrayList<>();

    public synchronized void register(SensitiveValue value) {
        values.add(value.use(chars -> chars.clone()));
    }

    public synchronized String redact(String input) {
        if (input == null) return null;
        String output = input;
        for (char[] value : values) {
            if (value.length > 0) output = output.replace(new String(value), "[REDACTED]");
        }
        return output;
    }

    @Override
    public synchronized void close() {
        values.forEach(value -> java.util.Arrays.fill(value, '\0'));
        values.clear();
    }
}
